import '../core/network/api_client.dart'; import '../models/payment.dart'; class PaymentRepository { PaymentRepository(this._api); final ApiClient _api; Future<PaymentModel> create(String orderId,String method,String key) async=>PaymentModel.fromJson(Map<String,dynamic>.from(await _api.post('/api/payments',body:{'orderId':orderId,'paymentMethod':method},headers:{'Idempotency-Key':key}))); Future<List<PaymentModel>> byOrder(String orderId) async { final r=await _api.get('/api/payments/order/$orderId'); return (r as List).whereType<Map<String,dynamic>>().map(PaymentModel.fromJson).toList(); } }